"""Build portable HTML from frozen data; does not fetch data or modify forecasts."""
import collections,html,json
from pathlib import Path
from core import verdict,total_goals_pick
ROOT=Path(__file__).resolve().parents[1]
def read(name):return json.loads((ROOT/'data'/name).read_text(encoding='utf-8'))
def explanation(c,p):
    if not p:return [],'自身样本不足，暂不预测。'
    parts=[]
    for name,side,venue in [(c['home_team'],p['home_inputs'],'home'),(c['away_team'],p['away_inputs'],'away')]:
        same=[r for r in side['rows'] if r['venue']==venue]
        current=[r for r in same if r['own_season']]
        rows=(current if len(current)>=2 else same)[:3]
        gf=sum(r['goals_for'] for r in rows);ga=sum(r['goals_against'] for r in rows)
        parts.append(f"{name}最近{len(rows)}个{'主场' if venue=='home' else '客场'}进{gf}球、失{ga}球")
    support='两队的得分与失球记录共同支持进球较多。' if total_goals_pick(p)>=3 else '两队攻防合并后，单项概率仍以2球及以下最高。'
    return ['；'.join(parts)+'。'+support], '单项概率接近，主选优势有限。' if sorted(p['probabilities'],reverse=True)[0]-sorted(p['probabilities'],reverse=True)[1]<.02 else '主选取概率最高的总进球档，不代表确定赛果。'
