JS='''
const D=JSON.parse(document.getElementById('board-data').textContent), history=D.mode==='history';
const labels={over:['大球侧','倾向3球以上'],under:['小球侧','倾向0–2球'],watch:['均衡','观望，方向不清晰'],missing:['暂缓判断','自身资料不足'],started:['未发布赛前预测','已开赛']};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const league=document.getElementById('league'), direction=document.getElementById('direction'),search=document.getElementById('search');
for(const name of [...new Set(D.matches.map(r=>r.league))].sort()){const o=document.createElement('option');o.value=name;o.textContent=name;league.append(o)}
let page=0;const size=history?20:100;
function details(r){if(!r.p)return '';const p=r.p;let body=`<p>主队预期进球 ${p.home_expected_goals.toFixed(2)} · 客队 ${p.away_expected_goals.toFixed(2)} · 总计 ${p.total_expected_goals.toFixed(2)}。<br>3球以上试算 ${(p.p3*100).toFixed(1)}%，不是经过前向验证的命中率。</p>`;
body+='<div class="scroll"><table><caption>总进球分布</caption><thead><tr>'+['0','1','2','3','4','5','6','7+'].map(x=>`<th scope="col">${x}球</th>`).join('')+'</tr></thead><tbody><tr>'+p.probabilities.map(x=>`<td>${(x*100).toFixed(1)}%</td>`).join('')+'</tr></tbody></table></div>';
if(r.inputs)for(const [name,s] of [[r.home,r.inputs.home],[r.away,r.inputs.away]]){body+=`<h4>${esc(name)} · 自身历史</h4><p>所用${s.n}场，同主客${s.venue_n}场，有效样本量${s.effective_n.toFixed(1)}；加权进球${s.gf.toFixed(2)}，失球${s.ga.toFixed(2)}。</p><table><thead><tr><th scope="col">日期</th><th scope="col">对手</th><th scope="col">场地</th><th scope="col">进／失球</th><th scope="col">权重</th></tr></thead><tbody>`+s.rows.map((x,i)=>`<tr><td>${esc(x.date)}</td><td>${esc(x.opponent)}</td><td>${x.venue==='home'?'主':'客'}</td><td>${x.goals_for}／${x.goals_against}</td><td>${s.weights[i].toFixed(3)}</td></tr>`).join('')+'</tbody></table>'}
if(r.hash)body+=`<p>逐场输入摘要 SHA-256<br><code>${esc(r.hash)}</code></p>`;
return `<details class="audit"><summary>核对这场依据</summary><div class="inside">${body}<p>${esc(r.caution)} 主选取完整分布中概率最高的一档；相同概率取较低档。7+合并7球及以上，不能当作恰好7球。仅90分钟总进球。</p></div></details>`}
function card(r){let context='';if(!history&&r.verdict!=='started')context=new Date(r.kickoff)<=new Date()?' · 已开赛，赛前留档':' · 赛前留档';
const pick=r.pick===null?null:(r.pick===7?'7+':String(r.pick));
const heading=pick===null?(r.verdict==='started'?'未发布赛前预测':'资料不足，暂不预测'):`主选 ${pick} 球`;
return `<article class="card ${r.pick===null?r.verdict:'picked'}" data-id="${esc(r.id)}" data-pick="${r.pick??''}"><div class="card-body"><div class="meta"><span class="tag">${esc(r.number||r.date)} · ${esc(r.league)}</span><span>${esc(r.time)}${context}</span></div><h3 class="teams">${esc(r.home)}<span class="vs" aria-label="对阵">VS</span>${esc(r.away)}</h3><div class="verdict"><i class="dot" aria-hidden="true"></i>${heading}</div>${r.reasons.length?'<p class="reasons" style="padding:0">'+r.reasons.map(esc).join('')+'</p>':`<p class="caution">${esc(r.caution)}</p>`}</div>${history?`<div class="result">实际 <strong>${r.actual} 球</strong> · ${r.pick===null?'未预测':(r.pick===Math.min(r.actual,7)?'主选命中':'主选未命中')}</div>`:''}${details(r)}</article>`}
function render(){const q=search.value.trim().toLowerCase();const rows=D.matches.filter(r=>(!league.value||r.league===league.value)&&(!direction.value||(direction.value==='missing'||direction.value==='started'?r.verdict===direction.value:String(r.pick)===direction.value))&&(!q||(r.home+r.away+r.number+r.league).toLowerCase().includes(q)));const pages=Math.max(1,Math.ceil(rows.length/size));page=Math.min(page,pages-1);document.getElementById('shown').textContent=`显示 ${rows.length} 场${history?' · 包含预测失败和资料不足':''}`;const slice=rows.slice(page*size,(page+1)*size);let out='';for(const group of [...new Set(slice.map(r=>r.group))]){out+=`<section aria-label="${esc(group)}"><div class="timehead"><h2>${esc(group)}</h2><span>${history?'按比赛日期回放':'北京时间'}</span></div><div class="grid">`+slice.filter(r=>r.group===group).map(card).join('')+'</div></section>'}document.getElementById('matches').innerHTML=out||'<p class="empty">没有符合条件的比赛。请清空搜索或更换筛选。</p>';document.getElementById('paging').hidden=!history;document.getElementById('page').textContent=`${page+1} / ${pages}`;document.getElementById('prev').disabled=page===0;document.getElementById('next').disabled=page>=pages-1;}
for(const el of [league,direction,search])el.addEventListener(el===search?'input':'change',()=>{page=0;render()});document.getElementById('reset').onclick=()=>{league.value='';direction.value='';search.value='';page=0;render()};document.getElementById('prev').onclick=()=>{page--;render();document.getElementById('shown').scrollIntoView()};document.getElementById('next').onclick=()=>{page++;render();document.getElementById('shown').scrollIntoView()};render();
'''
def compact(c,p):
    return {k:p[k] for k in ('home_expected_goals','away_expected_goals','total_expected_goals','p3','probabilities')} if p else None
def method(validation):
    comparisons=validation['comparisons'];rows=''
    for r in comparisons:
        if r['model']=='slow_own_blend':continue
        rows+=f"<tr><td>{'近30天' if r['period']=='last30' else '近20天'}</td><td>{'原同主客6场' if r['model']=='old_venue6' else '本版'}</td><td>{r['n']}</td><td>{r['brier3']:.4f}</td><td>{r['logloss']:.4f}</td></tr>"
    return '''<section class="method"><h2>主选怎么选</h2><p>每场分别读取两队自己的历史比赛。近期记录权重更高，同主客场权重更高；样本波动较大时，分布也会放宽。联赛只用于分组展示与筛选球队自身比赛，不提供共同进球均值或大球率。</p><p>资料不足就暂缓。首发、球员出场分钟及逐场xG尚未纳入验证，不作临场进球加减。主选是0、1、2、3、4、5、6、7+中概率最高的一档，不把总进球期望四舍五入成主选。</p><details><summary>模型改进与历史验证</summary><p>研究了Dixon–Coles的低比分修正、负二项分布与预测不确定性。只在较早开发样本上比较十种候选，选用本场自身样本的不确定性近似；不是完整贝叶斯模型。新增修正改善很小，主要改进来自扩大各队自身记录并做时间及主客权重。</p><p>回放10月1—30日全部369场，277场可预测，92场因资料不足留空。对照表只比较新旧都有输出的同一批场次。此前已看过部分10月结果，这属于回顾性检验，不是新盲测，也不冒充当时发布过的预测。</p><div class="scroll"><table><thead><tr><th>区间</th><th>算法</th><th>同场数</th><th>Brier 3+ ↓</th><th>对数损失 ↓</th></tr></thead><tbody>'''+rows+'''</tbody></table></div><p>本版近30天同场对照中，大球侧组平均试算约68%，实际约60%，仍偏乐观。本表衡量3+概率表现，不是单个进球数的命中率。卡片另按单项概率最高档给出唯一主选，历史回放也使用相同规则；概率相同取较低档，不因赛果改变选择。</p><p><a href="RESEARCH.md">研究来源与方法取舍</a> · <a href="data/audit.json">独立输入检查</a> · <a href="data/validation.json">完整回放数据</a> · <a href="README.md">复现说明</a></p></details></section>'''
def build(mode,today,validation):
    history=mode=='history';rows=[]
    if history:
        for item in sorted(validation['reviews'],key=lambda r:(r['case']['date'],r['case']['match_id']),reverse=True):
            c=item['case'];p=item['prediction'];reasons,caution=explanation(c,p)
            rows.append(dict(id=c['match_id'],home=c['home_team'],away=c['away_team'],league=c['competition'],date=c['date'],time='',number='',group=c['date'],verdict=verdict(p),reasons=reasons,caution=caution,p=compact(c,p),actual=item['actual_total_goals_90'],pick=total_goals_pick(p)))
    else:
        for item in sorted(today['matches'],key=lambda x:(x['verdict']=='started',x['kickoff'])):
            p=item['prediction'];c=item.get('case');reasons,caution=explanation(c,p) if c else ([], '本版采集时比赛已经开始，没有赛前发布记录；不根据赛果补做预测。')
            time=item['matchTime'][:5];date=item['matchDate']
            rows.append(dict(id=str(item['matchId']),home=item['homeTeamAllName'],away=item['awayTeamAllName'],league=item['leagueAbbName'],date=date,time=time,number=item['matchNumStr'],kickoff=item['kickoff'],group=('已开赛 · 未作预测' if item['verdict']=='started' else ('10月31日' if date=='2026-10-31' else '11月1日 · 周六业务日')+' '+time),verdict=item['verdict'],reasons=reasons,caution=caution,p=compact(c,p),inputs=dict(home=p['home_inputs'],away=p['away_inputs']) if p else None,hash=item.get('input_sha256'),pick=total_goals_pick(p)))
    payload=json.dumps(dict(mode=mode,matches=rows),ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
    title='把每一次判断留下来。' if history else '今晚的总进球观察'
    intro='逐场重算，逐场对照。预测失败与资料不足都保留，查看全部回放，也查看模型的局限。' if history else '每场一个总进球主选，一句比赛依据。'
    aside='<strong>历史回放，不是当时的发布记录</strong>按赛前日期截断球队历史，事后复算；10月数据此前已被查看，不能当作新的盲测。' if history else '<strong>各算各的，没有联赛平均补齐</strong>周六业务日含次日凌晨场次。早场已开赛的比赛留空；其余预测在开赛前冻结。'
    notice='这版有改善，仍会失误。高概率组仍偏乐观；全部回放包含未能判断的场次。' if history else '主选取单项概率最高的总进球数。7+表示7球及以上。首发未逐场确认；本页为赛前冻结快照。'
    available=[r for r in validation['reviews'] if r['prediction']]
    hits=sum(total_goals_pick(r['prediction'])==min(r['actual_total_goals_90'],7) for r in available)
    exact_note=f'<p>单个总进球档主选回放：{len(available)}场中命中{hits}场，约{hits/len(available):.1%}。这与3球以上的合计概率是不同指标；7+按合并档核对。</p>'
    method_html=method(validation).replace('<summary>模型改进与历史验证</summary>','<summary>模型改进与历史验证</summary>'+exact_note)
    stamp=today['forecast_at'][:19].replace('T',' ')
